-- Development intelligence references existing assessment and activity records.
-- No private coaching note or reflection is a source for these functions.
begin;
create schema development_internal;
revoke all on schema development_internal from public,anon,authenticated;
create table public.leadership_development_needs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), target_role_id uuid references roles(id), competency_id uuid references role_competencies(id), need_type text not null, title text not null, description text not null, source_type text not null, source_id uuid, source_key text not null, gap_severity text check(gap_severity in ('minor','moderate','significant','critical')), priority text not null default 'moderate' check(priority in ('low','moderate','high','urgent')), recommended_response text[] not null default '{}', status text not null default 'identified' check(status in ('identified','accepted','active','resolved','dismissed')), baseline_level numeric check(baseline_level between 1 and 5), target_level numeric check(target_level between 1 and 5), identified_at timestamptz not null default now(), identified_by uuid references auth.users(id), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, unique(candidate_id,source_key), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.leadership_development_needs enable row level security;
revoke all on public.leadership_development_needs from anon,authenticated;
create table public.development_method_rules(id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), competency_id uuid references role_competencies(id), competency_name text, need_type text, coaching_weight integer not null default 0 check(coaching_weight between 0 and 3), mentoring_weight integer not null default 0 check(mentoring_weight between 0 and 3), project_weight integer not null default 0 check(project_weight between 0 and 3), training_weight integer not null default 0 check(training_weight between 0 and 3), experience_weight integer not null default 0 check(experience_weight between 0 and 3), rationale text not null, version text not null, active boolean not null default true, created_by uuid references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_method_rules enable row level security;
revoke all on public.development_method_rules from anon,authenticated;
create table public.development_intelligence_versions(id uuid primary key default gen_random_uuid(), version text not null unique, matching_version text not null default 'v2-development', evidence_scoring_version text not null, matching_weights jsonb not null, evidence_weights jsonb not null, review_days integer not null default 90 check(review_days between 1 and 730), recency_days integer not null default 365 check(recency_days between 30 and 3650), minimum_independent_sources integer not null default 2 check(minimum_independent_sources between 1 and 20), created_by uuid references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_intelligence_versions enable row level security;
revoke all on public.development_intelligence_versions from anon,authenticated;
create table public.development_recommendations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), development_need_id uuid not null references leadership_development_needs(id), recommendation_type text not null, recommendation_data jsonb not null, reviewed_data jsonb, rationale text not null, source text not null default 'deterministic_rules' check(source='deterministic_rules'), model_version text not null, rule_id uuid references development_method_rules(id), status text not null default 'suggested' check(status in ('suggested','accepted','modified','dismissed','completed')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, unique(development_need_id,model_version,rule_id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_recommendations enable row level security;
revoke all on public.development_recommendations from anon,authenticated;
create table public.coaching_focus_areas(id uuid primary key default gen_random_uuid(), engagement_id uuid not null references coaching_engagements(id), development_need_id uuid references leadership_development_needs(id), competency_id uuid references role_competencies(id), title text not null, description text, baseline_level numeric check(baseline_level between 1 and 5), target_level numeric check(target_level between 1 and 5), priority text not null default 'moderate', status text not null default 'planned' check(status in ('planned','active','achieved','paused','closed')), created_by uuid references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.coaching_focus_areas enable row level security;
revoke all on public.coaching_focus_areas from anon,authenticated;
create table public.development_plan_steps(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), development_need_id uuid not null references leadership_development_needs(id), method text not null check(method in ('coaching','mentoring','project','training','experience','assessment','self_development')), title text not null, activity text not null, owner_user_id uuid references auth.users(id), target_date date, review_date date, evidence_required text not null, status text not null default 'planned' check(status in ('planned','active','completed','cancelled')), development_record_id uuid references development_records(id), project_assignment_id uuid references candidate_project_assignments(id), training_selection_id uuid references training_selections(id), mentor_assignment_id uuid references mentor_role_assignments(id), coaching_engagement_id uuid references coaching_engagements(id), created_by uuid references auth.users(id), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_plan_steps enable row level security;
revoke all on public.development_plan_steps from anon,authenticated;
create table public.development_evidence(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), development_need_id uuid references leadership_development_needs(id), competency_id uuid references role_competencies(id), coaching_engagement_id uuid references coaching_engagements(id), coaching_goal_id uuid references coaching_goals(id), project_assignment_id uuid references candidate_project_assignments(id), training_selection_id uuid references training_selections(id), mentor_assignment_id uuid references mentor_role_assignments(id), development_record_id uuid references development_records(id), evidence_type text not null, title text not null, description text not null, evidence_date date not null, source_user_id uuid not null references auth.users(id), visibility text not null default 'private' check(visibility in ('private','coach_client','organization','readiness_review')), verification_status text not null default 'self_reported' check(verification_status in ('unverified','self_reported','coach_confirmed','mentor_confirmed','manager_confirmed','verified')), verified_by uuid references auth.users(id), verified_at timestamptz, readiness_approved_by uuid references auth.users(id), readiness_approved_at timestamptz, scoring_version text not null, evidence_weight integer not null default 1 check(evidence_weight between 0 and 10), request_key uuid not null unique, created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_evidence enable row level security;
revoke all on public.development_evidence from anon,authenticated;
create table public.development_progress_reviews(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), engagement_id uuid references coaching_engagements(id), development_need_id uuid not null references leadership_development_needs(id), competency_id uuid references role_competencies(id), review_type text not null check(review_type in ('30_day','60_day','90_day','midpoint','closeout','custom')), baseline_level numeric check(baseline_level between 1 and 5), current_level numeric check(current_level between 1 and 5), progress_status text not null check(progress_status in ('not_started','early_progress','progressing','significant_progress','target_achieved','needs_attention','insufficient_evidence')), evidence_summary text not null, evidence_ids uuid[] not null default '{}', visibility text not null default 'coach_client' check(visibility in ('coach_client','organization','readiness_review')), reviewed_by uuid not null references auth.users(id), reviewed_at timestamptz not null default now(), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.development_progress_reviews enable row level security;
revoke all on public.development_progress_reviews from anon,authenticated;
create table public.readiness_history(id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), candidate_id uuid not null references candidates(id), target_role_id uuid not null references roles(id), previous_match_id uuid references candidate_role_matches(id), new_match_id uuid not null unique references candidate_role_matches(id), previous_readiness numeric, new_readiness numeric check(new_readiness between 0 and 100), reason text not null, supporting_evidence_ids uuid[] not null default '{}', changed_by uuid not null references auth.users(id), changed_at timestamptz not null default now(), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.readiness_history enable row level security;
revoke all on public.readiness_history from anon,authenticated;
create table public.coaching_outcome_measures(id uuid primary key default gen_random_uuid(), engagement_id uuid not null references coaching_engagements(id), development_need_id uuid references leadership_development_needs(id), competency_id uuid references role_competencies(id), measure_type text not null, baseline_value numeric, target_value numeric, final_value numeric, baseline_text text, target_text text, final_text text, measurement_source text not null, evidence_id uuid references development_evidence(id), visibility text not null default 'coach_client' check(visibility in ('coach_client','organization','readiness_review')), measured_by uuid references auth.users(id), measured_at timestamptz not null default now(), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.coaching_outcome_measures enable row level security;
revoke all on public.coaching_outcome_measures from anon,authenticated;
create table public.coach_development_experience(id uuid primary key default gen_random_uuid(), coach_id uuid not null references coach_profiles(id), need_type text not null, target_role_title text, description text not null, verified_by uuid not null references auth.users(id), unique(coach_id,need_type,target_role_title), created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default now());
alter table public.coach_development_experience enable row level security;
revoke all on public.coach_development_experience from anon,authenticated;
alter table coaching_goals add column focus_area_id uuid references coaching_focus_areas(id);
alter table coach_requests add column development_need_id uuid references leadership_development_needs(id);
alter table coaching_data_permissions drop constraint coaching_data_permissions_data_type_check;
alter table coaching_data_permissions add check(data_type in ('role_composite','competencies','clifton_strengths','assessment','360_review','development_plan','mentor_plan','project','training','readiness','development_need','target_role'));
insert into development_intelligence_versions(version,evidence_scoring_version,matching_weights,evidence_weights) values('development-rules-v1','evidence-v1','{"specialty":20,"competency":20,"development_need":15,"industry":10,"leadership_level":10,"target_role":10,"credential":5,"format":3,"availability":4,"geography":3}','{"unverified":0,"self_reported":1,"coach_confirmed":2,"mentor_confirmed":2,"manager_confirmed":3,"verified":3}');
insert into development_method_rules(competency_name,need_type,coaching_weight,mentoring_weight,project_weight,training_weight,experience_weight,rationale,version) values
('Executive Communication','executive_communication',3,2,2,1,2,'Focused practice, feedback and reflection can support executive communication; combine coaching with real presentations and mentor feedback.','method-v1'),
('Communication','executive_communication',3,2,2,1,2,'Communication can benefit from structured practice, feedback and accountability. Check the assessment context before choosing coaching.','method-v1'),
('Technical Accounting Knowledge','technical_knowledge',1,2,2,3,3,'Knowledge gaps usually need training and applied experience. Coaching is optional support, not a replacement for technical learning.','method-v1'),
